import { tags } from "typia";

/**
 * Comprehensive client device identification extracted from user agent strings.
 * This information enables platform optimization across different devices,
 * browsers, and operating systems while providing essential security monitoring
 * and compatibility testing capabilities for the shopping mall platform.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IDeviceInfo = {
  /**
   * Browser or application user agent string identifying the client device
   * type, operating system, and browser version. Used for compatibility
   * testing and device-specific feature detection.
   */
  userAgent: string & tags.MaxLength<1000>;

  /**
   * Operating system platform (Windows, macOS, Linux, iOS, Android) detected
   * from the user agent. Helps optimize user experience for specific
   * platforms and troubleshoot compatibility issues.
   */
  platform?: string | undefined;

  /**
   * Web browser name and version (Chrome, Firefox, Safari, Edge) extracted
   * from the user agent. Used for browser-specific optimizations and
   * compatibility testing.
   */
  browser?: string | undefined;

  /**
   * Device type classification based on screen size and capabilities.
   * Determines responsive layout, touch interactions, and feature
   * availability across different device categories.
   */
  deviceType?: "desktop" | "mobile" | "tablet" | "other" | undefined;
};
